// warranty css in product view: 
.warranty-selector {

  max-width: 500px;
}

.title {
  margin-bottom: 12px;
  font-size: 14px;
}

.title strong {
  font-weight: 700;
}

.title span {
  font-weight: 400;
}

.options {
  display: flex;
  align-items: center;
  gap: 12px;
}

.option {
  border: 2px solid #ccc;
  padding: 12px 16px;
flex:2;
line-height: 1.2;
  cursor: pointer;
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-width: 200px;
  transition: all 0.3s ease;
}

.m-label{
    display: flex;
    flex-direction: column;
}
.m-label strong {
  font-size: 14px;
  font-weight: 700;
}

.m-label span {
  font-size: 14px;
  font-weight: 400;
}

.option.selected {
  border-image: linear-gradient(to right, #9D34B4, #000000) 1;
}

.option .tick {
  display: none;
 
}

.option.selected .tick {
  display: block;
}

.help-container {
  position: relative;
}

.help {
  color: blue;
  font-size: 20px;
  cursor: pointer;
}

.tooltip {
  display: none;
  position: absolute;
  top: 30px;
  left: 0px;
  background-color: #fff;
  border: 1px solid #ccc;
  padding: 8px;
  border-radius: 6px;
  font-size: 13px;
  width: 240px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
  z-index: 10;
}

.help-container:hover .tooltip {
  display: block;
}
.productView-price .price{
    margin-top:10px !important;
    font-size: 35px !important;
    font-weight: 700 !important;
    color: #1D6448 !important;
}
