  display: flex;
  justify-content: space-around;
  background-color: #f2f2f2;
  padding: 20px 0;
  gap: 20px;
  flex-wrap: wrap;
  text-align: center;
}

.m-feature-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 120px;
  font-size: 14px;
  color: #000;
}

.m-icon {
  margin-bottom: 8px;
}


